INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Muss jede Funktion Fehler behandeln?', 2, '[{"text": "Nein", "correct": true, "because": "Kontextabhängig"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Fehlerhandling?', 3, '[{"text": "Robustheit erhöhen", "correct": true, "because": "Verhindert Abstürze"}, {"text": "Code schneller machen", "correct": false, "because": "Kein primärer Fokus"}, {"text": "UI gestalten", "correct": false, "because": "Kein direkter Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zum Fehlerhandling?', 5, '[{"text": "Ausnahmen", "correct": true, "because": "Fangen Fehler ab"}, {"text": "Statuscodes", "correct": true, "because": "Zeigen Fehler an"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}, {"text": "Datenkompression", "correct": false, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ausnahmen stoppen die Ausführung. b) Statuscodes sind nur für APIs.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Statuscodes auch lokal"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim Fehlerhandling?', 4, '[{"text": "Fehlerursache", "correct": false, "because": "Muss analysiert werden"}, {"text": "Reaktion auf Fehler", "correct": false, "because": "Definiert Verhalten"}, {"text": "Bildauflösung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob jede Ausnahme abgefangen werden muss?', 2, '[{"text": "Nein", "correct": true, "because": "Kann weitergeleitet werden"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Statuscode wähle ich für "Nicht gefunden"?', 3, '[{"text": "404", "correct": true, "because": "Standard für nicht gefunden"}, {"text": "500", "correct": false, "because": "Serverfehler"}, {"text": "200", "correct": false, "because": "Erfolg"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Fehlerhandling?', 5, '[{"text": "Stabilität", "correct": true, "because": "Verhindert Abstürze"}, {"text": "Nachvollziehbarkeit", "correct": true, "because": "Fehler identifizierbar"}, {"text": "Schnellere Ausführung", "correct": false, "because": "Kein direkter Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Try-Catch fängt Ausnahmen. b) Statuscodes sind optional. Stimmt das?', 3, '[{"text": "Beides stimmt", "correct": true, "because": "a) korrekt, b) kontextabhängig"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beides richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Fehlerhandling?', 4, '[{"text": "Fehlerbehandlung", "correct": false, "because": "Kern des Handlings"}, {"text": "Statusmeldung", "correct": false, "because": "Informiert über Fehler"}, {"text": "Grafikdesign", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist 500 ein Client-Fehler?', 2, '[{"text": "Nein", "correct": true, "because": "Serverfehler"}, {"text": "Ja", "correct": false, "because": "400er sind Client-Fehler"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken nutze ich für Fehlerhandling?', 4, '[{"text": "Try-Catch", "correct": true, "because": "Fängt Ausnahmen"}, {"text": "Statuscodes", "correct": true, "because": "Zeigt Fehler an"}, {"text": "UI-Rendering", "correct": false, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Fehlerhandling die Performance senkt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Minimaler Einfluss"}, {"text": "Ja", "correct": false, "because": "Schutz wichtiger"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim Fehlerhandling?', 3, '[{"text": "Fehlererkennung", "correct": true, "because": "Sichert Robustheit"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 400 zeigt Client-Fehler. b) Ausnahmen sind immer fatal.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Ausnahmen behandelbar"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken gibt es ohne Fehlerhandling?', 5, '[{"text": "Abstürze", "correct": true, "because": "Unbehandelte Fehler"}, {"text": "Unklare Fehlerursachen", "correct": true, "because": "Keine Rückmeldung"}, {"text": "Schnellere Laufzeit", "correct": false, "because": "Kein Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim Fehlerhandling unwichtig?', 3, '[{"text": "Fehlerprotokoll", "correct": false, "because": "Hilft bei Analyse"}, {"text": "Reaktion", "correct": false, "because": "Definiert Verhalten"}, {"text": "Serverdesign", "correct": true, "because": "Kein direkter Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ich Ausnahmen ignorieren?', 3, '[{"text": "Ja", "correct": true, "because": "Aber riskant"}, {"text": "Nein", "correct": false, "because": "Technisch möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 200 ein Fehlercode ist?', 2, '[{"text": "Nein", "correct": true, "because": "Erfolgscode"}, {"text": "Ja", "correct": false, "because": "200 bedeutet OK"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Statuscode wähle ich für einen Serverfehler?', 4, '[{"text": "500", "correct": true, "because": "Interner Serverfehler"}, {"text": "404", "correct": false, "because": "Nicht gefunden"}, {"text": "403", "correct": false, "because": "Zugriff verweigert"}]');
